            }
        }

        abstract static class Modulus<M extends Modulus<M>> {
            final java.util.List<Integer> factList = new java.util.ArrayList<>();
            final java.util.List<Integer> invFactList = new java.util.ArrayList<>();

            public abstract long modulus();

            public Modulus() {
                factList.add(1);
                invFactList.add(1);
            }

            public long fact(int n) {
                while (factList.size() <= n) {
                    int last = factList.get(factList.size() - 1);
                    factList.add((int) mult(last, factList.size()));
                }
                return factList.get(n);
            }

            public long fInv(int n) {
                int lastIdx = invFactList.size() - 1;
                if (lastIdx < n) {
                    long[] invArr = new long[n - lastIdx];
                    invArr[0] = inv(fact(n));
                    for (int i = 1; i < invArr.length; i++) {
                        invArr[i] = mult(invArr[i - 1], n - i + 1);
                    }
                    for (int i = invArr.length - 1; i >= 0; i--) {
                        invFactList.add((int) invArr[i]);
                    }
                }
                return invFactList.get(n);
            }

            public long ncr(int n, int r) {
                if (n < 0 || r < 0 || n < r) return 0;
                return mult(fact(n), mult(fInv(r), fInv(n - r)));
            }

            public long smallInv(int n) {
                return mult(fInv(n), fact(n - 1));
            }

            public long normalize(long x) {
                long m = modulus();
                x %= m;
                if (x < 0) x += m;
                return x;
            }

            public long add(long a, long b) {
                long s = a + b;
                long m = modulus();
                return s >= m ? s - m : s;
            }

            public long subtract(long a, long b) {
                long res = a - b;
                long m = modulus();
                return res < 0 ? res + m : res;
            }

            public long mult(long a, long b) {
                return (a * b) % modulus();
            }

            public long inv(long value) {
                long g = modulus(), x = 0, y = 1;
                for (long r = value; r != 0; ) {
                    long q = g / r;
                    long temp = g % r;
                    g = r;
                    r = temp;

                    long t = x - q * y;
                    x = y;
                    y = t;
                }
                assert g == 1;
                assert y == modulus() || y == -modulus();
                return normalize(x);
            }
        }
    }
