import sys

class NumberTheory:
    class Mod998:
        def __init__(self):
            self.modulus_value = 998244353
            self.fact_list = [1]
            self.inv_fact_list = [1]

        def modulus(self):
            return self.modulus_value

        def fact(self, n):
            while len(self.fact_list) <= n:
                last = self.fact_list[-1]
                self.fact_list.append((last * len(self.fact_list)) % self.modulus())
            return self.fact_list[n]

        def fInv(self, n):
            last_idx = len(self.inv_fact_list) - 1
            if last_idx < n:
                inv_arr = [0] * (n - last_idx)
                inv_arr[0] = self.inv(self.fact(n))
                for i in range(1, len(inv_arr)):
                    inv_arr[i] = (inv_arr[i - 1] * (n - i + 1)) % self.modulus()
                self.inv_fact_list.extend(inv_arr[::-1])
            return self.inv_fact_list[n]

        def ncr(self, n, r):
            if n < 0 or r < 0 or n < r:
                return 0
            return (self.fact(n) * self.inv(self.fInv(r)) * self.inv(self.fInv(n - r))) % self.modulus()

        def smallInv(self, n):
            return (self.fInv(n) * self.fact(n - 1)) % self.modulus()

        def normalize(self, x):
            m = self.modulus()
            x %= m
            if x < 0:
                x += m
            return x

        def add(self, a, b):
            s = a + b
            m = self.modulus()
            return s - m if s >= m else s

        def subtract(self, a, b):
            res = a - b
            m = self.modulus()
            return res + m if res < 0 else res

        def mult(self, a, b):
            return (a * b) % self.modulus()

        def inv(self, value):
            g, x, y = self.modulus(), 0, 1
            r = value
            while r != 0:
                q = g // r
                g, r = r, g % r
                x, y = y, x - q * y
            assert g == 1
            assert y == self.modulus() or y == -self.modulus()
            return self.normalize(x)

def main():
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    m = int(input_data[1])

    mod = NumberTheory.Mod998()
    mod.fInv(n + m)
    phaseSize = 1
    p = 1
    i = 0
    while p != 0:
        p = (p * (n - i) * mod.inv(n + m - i)) % mod.modulus()
        phaseSize = (phaseSize + p) % mod.modulus()
        i += 1

    answer = 0
    for k in range(1, n + 1):
        numPhases = ((m + k) * mod.smallInv(k)) % mod.modulus()
        term = (mod.ncr(n, k) * numPhases * phaseSize) % mod.modulus()
        if k % 2 == 1:
            answer = (answer + term) % mod.modulus()
        else:
            answer = (answer - term) % mod.modulus()

    print(answer)

if __name__ == "__main__":
    main()

